local R=dofile('tests/kernel_vehicles_harness.lua')
local H,n=R.H,0
local function case(name,fn,options)R.menuCase(name,fn,options);n=n+1 end
case('menu categories',function(r)r.menu.openVehiclesMenu();assert(r.last.menu=='forge_core_server_settings'and #r.last.options==4)end)
case('parent routes',function(r)r.menu.openServerSettingsMenu();r.select(8);assert(r.last.id=='forge_core_vehicles')end)
case('denied payload',function(r)r.vehicleHook=function()return false,'no_permission'end;r.menu.openVehiclesMenu()end)
case('bad payload',function(r)r.vehicleHook=function()return true,false end;r.menu.openVehiclesMenu()end)
case('category list and image',function(r)r.menu.openVehiclesCategory('sports');assert(r.last.options[1].image:find('/vehicles/sultan.webp',1,true))end)
case('category order custom',function(r)r.payload.vehicles[2]=H.copy(r.vehicle);r.payload.vehicles[2].model='other';r.payload.vehicles[2].category='weird';r.menu.openVehiclesMenu()end)
case('details parent',function(r)r.menu.openVehicleDetails(r.vehicle,'sports');assert(r.last.menu=='forge_core_vehicles_category_sports')end)
case('inactive disables spawn',function(r)r.vehicle.active=false;r.menu.openVehicleDetails(r.vehicle);assert(r.last.options[2].disabled and r.last.options[3].disabled)end)
case('create editor cancelled',function(r)r.menu.openVehicleEditor()end)
case('category editor cancelled',function(r)r.menu.openVehicleEditor(r.vehicle,'sports')end)
case('editor options custom',function(r)
    r.vehicle.type='custom';r.vehicle.category='custom'
    r.inputHook=function(_,fields)assert(#fields==11 and fields[1].disabled and fields[4].type=='number');return nil end
    r.menu.openVehicleEditor(r.vehicle)
end)
case('editor save',function(r)r.inputs={{'ignored','New','Brand',123,'sports','A','bike','sultan',5,'shop','false'}};r.menu.openVehicleEditor(r.vehicle,'sports');r.runTimers()end)
case('create save',function(r)r.inputs={{'new','New','Brand',123,'sports','A','bike','new',5,'','true'}};r.menu.openVehicleEditor();r.runTimers()end)
case('editor save failed reopens',function(r)r.inputs={{'new','New','Brand',123,'sports','A','bike','new',5,'','true'}};r.vehicleHook=function(name)if name==r.config.Vehicles.Callbacks.save then return false,'save_failed'end;return true,r.payload end;r.menu.openVehicleEditor();r.runTimers(450)end)
case('import',function(r)r.menu.openVehiclesMenu();r.inputs={{'model="new"'}};r.select(2);r.runTimers()end)
case('import cancel',function(r)r.menu.openVehiclesMenu();r.select(2)end)
case('reload',function(r)r.menu.openVehiclesMenu();r.select(3);r.runTimers()end)
case('toggle active',function(r)r.menu.openVehicleDetails(r.vehicle,'sports');r.select(4);r.runTimers()end)
case('delete confirm',function(r)r.menu.openVehicleDetails(r.vehicle,'sports');r.alerts={'confirm'};r.select(6);r.runTimers()end)
case('delete cancel',function(r)r.menu.openVehicleDetails(r.vehicle);r.alerts={'cancel'};r.select(6);r.runTimers()end)
case('double action lock',function(r)r.menu.openVehicleDetails(r.vehicle);local ctx=r.last;r.select(4,ctx);r.select(4,ctx);assert(#r.saved==1)end)
case('snapshot callback valid',function(r)return r.callbacks[r.config.Vehicles.Callbacks.getCurrentVehicle]()end)
case('snapshot not in vehicle',function(r)r.inVehicle=false;return r.callbacks[r.config.Vehicles.Callbacks.getCurrentVehicle]()end)
case('snapshot properties unavailable',function(r)r.library.fivem.getVehicleProperties=nil;return r.callbacks[r.config.Vehicles.Callbacks.getCurrentVehicle]()end)
case('snapshot malformed properties',function(r)r.snapshotProps=false;return r.callbacks[r.config.Vehicles.Callbacks.getCurrentVehicle]()end)
case('snapshot register network',function(r)r.networked=false;return r.callbacks[r.config.Vehicles.Callbacks.getCurrentVehicle]()end)
case('snapshot network timeout',function(r)r.networked=false;r.networkFail=true;return r.callbacks[r.config.Vehicles.Callbacks.getCurrentVehicle]()end)
case('snapshot deleted during network wait',function(r)r.netId=0;r.waitHook=function()r.entities[100]=nil end;return r.callbacks[r.config.Vehicles.Callbacks.getCurrentVehicle]()end)
case('snapshot archetype optional',function(r)return r.callbacks[r.config.Vehicles.Callbacks.getCurrentVehicle]()end,function(r)r.native.GetEntityArchetypeName=false end)
case('temporary spawn',function(r)r.menu.openVehicleDetails(r.vehicle);r.select(2)end)
case('permanent spawn',function(r)r.menu.openVehicleDetails(r.vehicle);r.alerts={'confirm'};r.select(3)end)
case('permanent declined',function(r)r.menu.openVehicleDetails(r.vehicle);r.alerts={'cancel'};r.select(3)end)
case('spawn unavailable',function(r)r.library.fivem.streaming=nil;r.menu.openVehicleDetails(r.vehicle);r.select(2)end)
case('spawn ped absent',function(r)r.ped=0;r.menu.openVehicleDetails(r.vehicle);r.select(2)end)
case('spawn creation failed',function(r)r.spawnResult=0;r.menu.openVehicleDetails(r.vehicle);r.select(2)end)
case('spawn ground fallback',function(r)r.noGround=true;r.menu.openVehicleDetails(r.vehicle);r.select(2)end)
case('spawn server denies delete',function(r)r.vehicleHook=function()return false,'no_permission'end;r.menu.openVehicleDetails(r.vehicle);r.select(2);assert(r.entities[100]==nil)end)
case('permanent snapshot fails delete',function(r)r.snapshotProps=false;r.menu.openVehicleDetails(r.vehicle);r.alerts={'confirm'};r.select(3);assert(r.entities[100]==nil)end)
case('temporary snapshot fails still calls server',function(r)r.snapshotProps=false;r.menu.openVehicleDetails(r.vehicle);r.select(2);assert(#r.saved==1)end)
print('PASS vehicle menu/client differentials '..n)
